(1200,92,N'8.33',N'TIN-02',N'Sensitive And Personal Data Avoidance',N'The organisation must define, implement and maintain practical controls for sensitive and personal data avoidance, proportionate to information classification, business need and security risk. It also covers data masking removal and de-identification. The purpose is to ensure sensitive and personal data avoidance is authorized, effective, monitored and supported by evidence. It also aims to ensure data masking removal and de-identification is authorized, effective, monitored and supported by evidence.',N'Ensure sensitive and personal data avoidance is authorized, effective, monitored and supported by evidence. Ensure data masking removal and de-identification is authorized, effective, monitored and supported by evidence.',N'sensitive and personal data avoidance; technology security; 8.33; data masking removal and de-identification',0,N'Reviewed - all merged sources addressed');

INSERT #prac(seq,sheet_statement_id,statement_reference,practice_ref,practice_name,practice_statement,objective,keywords,is_merged,merge_status) VALUES
(1201,92,N'8.33',N'TIN-03',N'Production-Equivalent Test Access Controls',N'The organisation must define, implement and maintain practical controls for production-equivalent test access controls, proportionate to information classification, business need and security risk. The purpose is to ensure production-equivalent test access controls is authorized, effective, monitored and supported by evidence.',N'Ensure production-equivalent test access controls is authorized, effective, monitored and supported by evidence.',N'production-equivalent test access controls; technology security; 8.33',1,N'Merged into TIN-05 — Merged'),
(1202,92,N'8.33',N'TIN-04',N'Copy-Specific Authorization For Operational Data',N'The organisation must define, implement and maintain practical controls for copy-specific authorization for operational data, proportionate to information classification, business need and security risk. The purpose is to ensure copy-specific authorization for operational data is authorized, effective, monitored and supported by evidence.',N'Ensure copy-specific authorization for operational data is authorized, effective, monitored and supported by evidence.',N'copy-specific authorization for operational data; technology security; 8.33',0,N'Standalone - not merged'),
(1203,92,N'8.33',N'TIN-05',N'Test Data Copying And Use Logging',N'The organisation must define, implement and maintain practical controls for test data copying and use logging, proportionate to information classification, business need and security risk. It must test Data Integrity And Tamper Protection. It also covers cloud test information protection. It must test Data Inventory Retention And Review. It must test Information Selection And Reliability. It also covers production-equivalent test access controls. It also covers post-test secure information deletion. The purpose is to ensure test data copying and use logging is authorized, effective, monitored and supported by evidence. It also aims to ensure test data integrity and tamper protection is authorized, effective, monitored and supported by evidence. It also aims to ensure cloud test information protection is authorized, effective, monitored and supported by evidence. It also aims to ensure test data inventory retention and review is authorized, effective, monitored and supported by evidence. It also aims to ensure test information selection and reliability is authorized, effective, monitored and supported by evidence. It also aims to ensure production-equivalent test access controls is authorized, effective, monitored and supported by evidence. It also aims to ensure post-test secure information deletion is authorized, effective, monitored and supported by evidence.',N'Ensure test data copying and use logging is authorized, effective, monitored and supported by evidence. Ensure test data integrity and tamper protection is authorized, effective, monitored and supported by evidence. Ensure cloud test information protection is authorized, effective, monitored and supported by evidence. Ensure test data inventory retention and review is authorized, effective, monitored and supported by evidence. Ensure test information selection and reliability is authorized, effective, monitored and supported by evidence; Ensure production-equivalent test access controls is authorized, effective, monitored and supported by evidence; Ensure post-test secure information deletion is authorized, effective, monitored and supported by evidence.',N'test information selection and reliability; technology security; 8.33; production-equivalent test access controls; test data copying and use logging; test data integrity and tamper protection; cloud test information protection; test data inventory retention and review; post-test secure information deletion',0,N'Reviewed - all merged sources addressed'),
(1204,92,N'8.33',N'TIN-06',N'Data Masking Removal And De-Identification',N'The organisation must define, implement and maintain practical controls for data masking removal and de-identification, proportionate to information classification, business need and security risk. The purpose is to ensure data masking removal and de-identification is authorized, effective, monitored and supported by evidence.',N'Ensure data masking removal and de-identification is authorized, effective, monitored and supported by evidence.',N'data masking removal and de-identification; technology security; 8.33',1,N'Merged into TIN-02 — Merged'),
(1205,92,N'8.33',N'TIN-07',N'Post-Test Secure Information Deletion',N'The organisation must define, implement and maintain practical controls for post-test secure information deletion, proportionate to information classification, business need and security risk. The purpose is to ensure post-test secure information deletion is authorized, effective, monitored and supported by evidence.',N'Ensure post-test secure information deletion is authorized, effective, monitored and supported by evidence.',N'post-test secure information deletion; technology security; 8.33',1,N'Merged into TIN-05 — Merged'),
(1206,92,N'8.33',N'TIN-08',N'Test Information Selection And Reliability and Related Controls',N'Define, implement and maintain practical controls for test information selection and reliability, proportionate to information classification, business need and security risk.',N'Ensure test information selection and reliability is authorized, effective, monitored and supported by evidence.',N'test information selection and reliability; technology security; 8.33',0,N'Added from obligation registers — name variant; review required'),
(1207,92,N'8.33',N'TIN-09',N'Test Data Copying And Use Logging and Related Controls',N'The organisation must define, implement and maintain practical controls for test data copying and use logging, proportionate to information classification, business need and security risk. It must test Data Integrity And Tamper Protection. It also covers cloud test information protection. It must test Data Inventory Retention And Review. It must test Information Selection And Reliability. It also covers production-equivalent test access controls. It also covers post-test secure information deletion. The purpose is to ensure test data copying and use logging is authorized, effective, monitored and supported by evidence. It also aims to ensure test data integrity and tamper protection is authorized, effective, monitored and supported by evidence. It also aims to ensure cloud test information protection is authorized, effective, monitored and supported by evidence. It also aims to ensure test data inventory retention and review is authorized, effective, monitored and supported by evidence. It also aims to ensure test information selection and reliability is authorized, effective, monitored and supported by evidence. It also aims to ensure production-equivalent test access controls is authorized, effective, monitored and supported by evidence. It also aims to ensure post-test secure information deletion is authorized, effective, monitored and supported by evidence.',N'Ensure test data copying and use logging is authorized, effective, monitored and supported by evidence. Ensure test data integrity and tamper protection is authorized, effective, monitored and supported by evidence. Ensure cloud test information protection is authorized, effective, monitored and supported by evidence. Ensure test data inventory retention and review is authorized, effective, monitored and supported by evidence. Ensure test information selection and reliability is authorized, effective, monitored and supported by evidence; Ensure production-equivalent test access controls is authorized, effective, monitored and supported by evidence; Ensure post-test secure information deletion is authorized, effective, monitored and supported by evidence.',N'test information selection and reliability; technology security; 8.33; production-equivalent test access controls; test data copying and use logging; test data integrity and tamper protection; cloud test information protection; test data inventory retention and review; post-test secure information deletion',0,N'Added from obligation registers — name variant; review required'),
(1208,92,N'8.33',N'TIN-10',N'Post-Test Secure Information Deletion and Related Controls',N'Define, implement and maintain practical controls for post-test secure information deletion, proportionate to information classification, business need and security risk.',N'Ensure post-test secure information deletion is authorized, effective, monitored and supported by evidence.',N'post-test secure information deletion; technology security; 8.33',0,N'Added from obligation registers — name variant; review required'),
(1209,93,N'8.34',N'ATS-01',N'Audit Testing Planning And Management Agreement',N'The organisation must plan audit tests and assurance activities affecting operational systems, and obtain agreement between the tester and appropriate management before work begins. It also covers technical audit scope control. It also covers audit device security verification. It also covers availability-safe audit scheduling. The purpose is to ensure audit testing is authorized, coordinated and designed to minimize disruption to systems and business processes. It also aims to prevent uncontrolled testing and limit audit activity to the approved purpose and scope. It also aims to prevent audit devices from introducing threats or weaknesses into assessed environments. It also aims to minimize disruption to operational systems and business processes during audit testing.',N'Ensure audit testing is authorized, coordinated and designed to minimize disruption to systems and business processes. Prevent uncontrolled testing and limit audit activity to the approved purpose and scope; Prevent audit devices from introducing threats or weaknesses into assessed environments; Minimize disruption to operational systems and business processes during audit testing.',N'audit planning; management agreement; assurance activity; operational systems; audit testing security; 8.34; technical audit; scope; test boundaries; change control; audit device; endpoint security; antimalware; patching',0,N'Reviewed - all merged sources addressed'),
(1210,93,N'8.34',N'ATS-02',N'System And Data Access Approval',N'The organisation must define, approve and document audit requests for access to operational systems and data before access is granted. The purpose is to ensure audit access is necessary, authorized, limited and accountable.',N'Ensure audit access is necessary, authorized, limited and accountable.',N'audit access; system access; data access; management approval; audit testing security; 8.34',1,N'Merged into ATS-09 — Merged'),
(1211,93,N'8.34',N'ATS-03',N'Technical Audit Scope Control',N'The organisation must agree and control the scope, methods, targets and boundaries of technical audit tests before execution. The purpose is to prevent uncontrolled testing and limit audit activity to the approved purpose and scope.',N'Prevent uncontrolled testing and limit audit activity to the approved purpose and scope.',N'technical audit; scope; test boundaries; change control; audit testing security; 8.34',1,N'Merged into ATS-01 — Merged'),
(1212,93,N'8.34',N'ATS-04',N'Read-Only And Administrator-Assisted Testing',N'The organisation must use read-only access for audit testing and, where unavailable, require an experienced authorized administrator to perform the test for the auditor. The purpose is to prevent unauthorized or accidental changes to operational software and data during audit testing.',N'Prevent unauthorized or accidental changes to operational software and data during audit testing.',N'read-only access; administrator-assisted testing; least privilege; operational data; audit testing security; 8.34',0,N'Standalone - not merged'),
(1213,93,N'8.34',N'ATS-05',N'Audit Device Security Verification',N'The organisation must establish and verify security requirements, including malware protection and patching, for devices used to access systems during audit testing. The purpose is to prevent audit devices from introducing threats or weaknesses into assessed environments.',N'Prevent audit devices from introducing threats or weaknesses into assessed environments.',N'audit device; endpoint security; antimalware; patching; audit testing security; 8.34',1,N'Merged into ATS-01 — Merged'),
(1214,93,N'8.34',N'ATS-06',N'Isolated System Copy Protection And Disposal',N'The organisation must allow non-read-only activity only on isolated copies, protect retained copies and securely delete copies when audit work is complete. It also covers development and test environment audit protection. The purpose is to protect system files used for audit testing from unauthorized use, disclosure or retention. It also aims to prevent assurance activity from damaging code or exposing sensitive information outside production.',N'Protect system files used for audit testing from unauthorized use, disclosure or retention. Prevent assurance activity from damaging code or exposing sensitive information outside production.',N'isolated copy; system files; secure deletion; audit records; audit testing security; 8.34; development environment; test environment; code integrity; sensitive information',0,N'Reviewed - all merged sources addressed'),
(1215,93,N'8.34',N'ATS-07',N'Special Processing And Audit Tool Approval',N'The organisation must identify, assess and approve requests for special or additional processing, including the use of audit tools. The purpose is to control elevated or unusual audit activity that can affect system security or operation.',N'Control elevated or unusual audit activity that can affect system security or operation.',N'audit tools; special processing; approval; elevated activity; audit testing security; 8.34',1,N'Merged into ATS-09 — Merged'),
(1216,93,N'8.34',N'ATS-08',N'Availability-Safe Audit Scheduling',N'The organisation must schedule audit tests that can affect system availability outside business hours or within an approved low-impact maintenance window. The purpose is to minimize disruption to operational systems and business processes during audit testing.',N'Minimize disruption to operational systems and business processes during audit testing.',N'availability; audit schedule; business hours; maintenance window; audit testing security; 8.34',1,N'Merged into ATS-01 — Merged'),
(1217,93,N'8.34',N'ATS-09',N'Audit Access Monitoring And Logging',N'The organisation must monitor and log all access performed for audit and assurance testing, and retain records for investigation and accountability. It also covers system and data access approval. It also covers special processing and audit tool approval. The purpose is to provide traceability and timely detection of inappropriate audit access or activity. It also aims to ensure audit access is necessary, authorized, limited and accountable. It also aims to control elevated or unusual audit activity that can affect system security or operation.',N'Provide traceability and timely detection of inappropriate audit access or activity. Ensure audit access is necessary, authorized, limited and accountable; Control elevated or unusual audit activity that can affect system security or operation.',N'audit access; system access; data access; management approval; audit testing security; 8.34; audit tools; special processing; approval; elevated activity; audit logging; monitoring; traceability; access records',0,N'Reviewed - all merged sources addressed'),
(1218,93,N'8.34',N'ATS-10',N'Development And Test Environment Audit Protection',N'The organisation must apply audit testing safeguards to development and test environments to protect code integrity and sensitive information. The purpose is to prevent assurance activity from damaging code or exposing sensitive information outside production.',N'Prevent assurance activity from damaging code or exposing sensitive information outside production.',N'development environment; test environment; code integrity; sensitive information; audit testing security; 8.34',1,N'Merged into ATS-06 — Merged');

GO

BEGIN TRY
BEGIN TRANSACTION;

-- ---------------------------------------------------------------
-- Configuration
-- ---------------------------------------------------------------
DECLARE @by NVARCHAR(100) = N'anoop.ps@soffit.in';

-- 1 = trust the sheet's framework_statement_id (and verify it against the
--     control reference).  0 = ignore the ids and match on the control
--     reference alone.  See the header.
DECLARE @resolve_by_statement_id BIT = 1;

-- 1 = refresh description / objective / keywords on Practices that
--     already exist.  0 = leave them exactly as they are.
DECLARE @overwrite_existing BIT = 0;

DECLARE @release_id     BIGINT;
DECLARE @practice_start INT;
DECLARE @inserted INT = 0, @updated INT = 0, @mapped INT = 0;
DECLARE @sheet_rows INT = (SELECT COUNT(*) FROM #prac);
DECLARE @missing NVARCHAR(4000), @error NVARCHAR(4000);

-- ---------------------------------------------------------------
-- Preflight
-- ---------------------------------------------------------------
IF SCHEMA_ID('GRAC_New') IS NULL
    THROW 50520, 'Schema GRAC_New is missing. Run 001 first.', 1;
IF OBJECT_ID('GRAC_New.requirement','U') IS NULL
    THROW 50521, 'GRAC_New.requirement is missing. Run 001 first.', 1;
IF OBJECT_ID('GRAC_New.framework_statement','U') IS NULL
    THROW 50522, 'GRAC_New.framework_statement is missing. Run 001 and 052 first.', 1;
IF OBJECT_ID('GRAC_New.framework_statement_requirement_map','U') IS NULL
    THROW 50523, 'GRAC_New.framework_statement_requirement_map is missing. Run 001 first.', 1;
IF COL_LENGTH('GRAC_New.requirement','keywords') IS NULL
    THROW 50524, 'requirement.keywords is missing. Run 023_keywords_obligation_and_practice.sql first.', 1;
IF NOT EXISTS(SELECT 1 FROM GRAC_New.framework_statement WHERE status = N'Active')
    THROW 50525, 'No active Framework Statements. Run 052_iso_27001_source_statements.sql first.', 1;

IF @sheet_rows <> 1218
BEGIN
    SET @error = CONCAT(N'Staging holds ', @sheet_rows, N' rows, expected 1218. The INSERT #prac block above is incomplete -- do not load a partial catalogue.');
    THROW 50526, @error, 1;
END

-- ---------------------------------------------------------------
-- Validation
-- ---------------------------------------------------------------

-- 1. The sheet's own Practice Names must be unique.  061-065 resolve every
--    Obligation by name, so a duplicate here would make thousands of
--    Obligations ambiguous.
IF EXISTS(SELECT 1 FROM #prac GROUP BY practice_name HAVING COUNT(*) > 1)
BEGIN
    SET @missing = STUFF((SELECT N', ' + x.practice_name FROM
        (SELECT practice_name FROM #prac GROUP BY practice_name HAVING COUNT(*) > 1) x
        FOR XML PATH('')), 1, 2, N'');
    SET @error = CONCAT(N'Duplicate Practice Name(s) in the sheet: ', @missing,
                        N'. 061-065 key on the name; resolve the duplicates in the workbook first.');
    THROW 50527, @error, 1;
END

-- 2 / 3. Statement resolution -- see the header.
IF @resolve_by_statement_id = 1
BEGIN
    IF EXISTS(SELECT 1 FROM #prac p
              WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.framework_statement fs
                               WHERE fs.framework_statement_id = p.sheet_statement_id))
    BEGIN
        SET @missing = STUFF((
            SELECT DISTINCT N', ' + CAST(p.sheet_statement_id AS NVARCHAR(20)) + N' (' + p.statement_reference + N')'
            FROM #prac p
            WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.framework_statement fs
                             WHERE fs.framework_statement_id = p.sheet_statement_id)
            FOR XML PATH('')), 1, 2, N'');
        SET @error = CONCAT(N'framework_statement_id(s) not found: ', @missing,
                            N'. Load the Statements first, or set @resolve_by_statement_id = 0 to match on the control reference instead.');
        THROW 50528, @error, 1;
    END

    IF EXISTS(SELECT 1 FROM #prac p
              JOIN GRAC_New.framework_statement fs ON fs.framework_statement_id = p.sheet_statement_id
              WHERE fs.statement_reference <> p.statement_reference)
    BEGIN
        SET @missing = STUFF((
            SELECT DISTINCT N', ' + CAST(p.sheet_statement_id AS NVARCHAR(20))
                          + N': sheet says ' + p.statement_reference
                          + N', database says ' + fs.statement_reference
            FROM #prac p
            JOIN GRAC_New.framework_statement fs ON fs.framework_statement_id = p.sheet_statement_id
            WHERE fs.statement_reference <> p.statement_reference
            FOR XML PATH('')), 1, 2, N'');
        SET @error = CONCAT(N'framework_statement_id does not match the control reference for: ', @missing,
                            N'. The sheet was exported from a different database. Set @resolve_by_statement_id = 0, or re-export the sheet from this environment.');
        THROW 50529, @error, 1;
    END
END
ELSE
BEGIN
    IF EXISTS(SELECT 1 FROM #prac p
              WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.framework_statement fs
                               WHERE fs.statement_reference = p.statement_reference))
    BEGIN
        SET @missing = STUFF((
            SELECT DISTINCT N', ' + p.statement_reference FROM #prac p
            WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.framework_statement fs
                             WHERE fs.statement_reference = p.statement_reference)
            FOR XML PATH('')), 1, 2, N'');
        SET @error = CONCAT(N'Framework Statement(s) not found by reference: ', @missing, N'.');
        THROW 50530, @error, 1;
    END
END

-- Resolve each sheet row to exactly one statement.  Everything below reads
-- #stmt and never re-decides.
SELECT p.seq, fs.framework_statement_id, fs.release_id
INTO #stmt
FROM #prac p
JOIN GRAC_New.framework_statement fs
  ON (@resolve_by_statement_id = 1 AND fs.framework_statement_id = p.sheet_statement_id)
  OR (@resolve_by_statement_id = 0 AND fs.statement_reference    = p.statement_reference);
CREATE UNIQUE CLUSTERED INDEX ux_stmt_seq ON #stmt(seq);

-- 4. Exactly one statement per sheet row -- in reference mode a duplicated
--    statement_reference across releases would otherwise fan the row out.
IF (SELECT COUNT(*) FROM #stmt) <> @sheet_rows
BEGIN
    SET @error = CONCAT(N'Statement resolution produced ', (SELECT COUNT(*) FROM #stmt),
                        N' rows for ', @sheet_rows, N' sheet rows. A control reference resolves to more than one Statement -- load one release at a time.');
    THROW 50531, @error, 1;
END

-- 5. All resolved statements must belong to ONE release.
IF (SELECT COUNT(DISTINCT release_id) FROM #stmt) > 1
BEGIN
    SET @error = N'The mapped Framework Statements belong to more than one Release. Load one release at a time.';
    THROW 50532, @error, 1;
END
SELECT TOP 1 @release_id = release_id FROM #stmt;

-- 6. No Practice Name may already exist more than once in the database.
IF EXISTS(SELECT 1
          FROM GRAC_New.requirement r
          WHERE EXISTS(SELECT 1 FROM #prac p WHERE p.practice_name = r.requirement_name)
          GROUP BY r.requirement_name HAVING COUNT(*) > 1)
BEGIN
    SET @missing = STUFF((
        SELECT N', ' + x.requirement_name
        FROM (SELECT r.requirement_name
              FROM GRAC_New.requirement r
              WHERE EXISTS(SELECT 1 FROM #prac p WHERE p.practice_name = r.requirement_name)
              GROUP BY r.requirement_name HAVING COUNT(*) > 1) x
        FOR XML PATH('')), 1, 2, N'');
    SET @error = CONCAT(N'Practice Name(s) already present more than once in GRAC_New.requirement: ', @missing,
                        N'. Run 058 to reset, or resolve the duplicates -- this load and 061-065 both key on the name.');
    THROW 50533, @error, 1;
END

PRINT CONCAT(N'Statement resolution: ',
             CASE WHEN @resolve_by_statement_id = 1
                  THEN N'by sheet framework_statement_id, verified against the control reference'
                  ELSE N'by control reference (sheet ids ignored)' END,
             N' | Release ', @release_id, N'.');

-- ---------------------------------------------------------------
-- Practice Code allocation
--
-- Same rule and same numbering as cm_manage_repository (migration 050):
-- continue from the highest PR-### already in use.  UPDLOCK + HOLDLOCK
-- serialize against a concurrent interactive save inside this
-- transaction, so the block cannot be claimed twice.
--
-- FORMAT(..., '000') pads to at least three digits and does not truncate,
-- so this catalogue runs PR-001 .. PR-1218.
-- ---------------------------------------------------------------
SELECT @practice_start = ISNULL(MAX(TRY_CONVERT(INT, SUBSTRING(requirement_code, 4, 50))), 0) + 1
FROM GRAC_New.requirement WITH (UPDLOCK, HOLDLOCK)
WHERE requirement_code LIKE N'PR-[0-9]%'
  AND TRY_CONVERT(INT, SUBSTRING(requirement_code, 4, 50)) IS NOT NULL;

-- ---------------------------------------------------------------
-- Insert new Practices
-- ---------------------------------------------------------------
DECLARE @new TABLE(requirement_id BIGINT, requirement_code NVARCHAR(100), requirement_name NVARCHAR(300), seq INT);

;WITH pending AS (
    SELECT p.seq, p.practice_name, p.practice_statement, p.objective, p.keywords,
           ROW_NUMBER() OVER (ORDER BY p.seq) AS rn
    FROM #prac p
    WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.requirement r
                     WHERE r.requirement_name = p.practice_name))
INSERT GRAC_New.requirement
    (requirement_code, requirement_name, requirement_statement, objective, keywords, status, entered_by)
OUTPUT inserted.requirement_id, inserted.requirement_code, inserted.requirement_name, 0 INTO @new
SELECT CONCAT(N'PR-', FORMAT(@practice_start + pending.rn - 1, N'000')),
       pending.practice_name, pending.practice_statement, pending.objective, pending.keywords,
       N'Active', @by
FROM pending;

SET @inserted = @@ROWCOUNT;

-- Defensive: 050 skips a generated number already taken by a legacy
-- hand-typed code.  Starting above MAX(PR-###) makes that impossible here,
-- but assert it rather than assume it.
IF EXISTS(SELECT 1 FROM GRAC_New.requirement GROUP BY requirement_code HAVING COUNT(*) > 1)
BEGIN
    SET @error = N'Practice Code collision detected after insert. No codes were committed.';
    THROW 50534, @error, 1;
END

-- ---------------------------------------------------------------
-- Optional refresh of Practices that already exist
-- ---------------------------------------------------------------
IF @overwrite_existing = 1
BEGIN
    UPDATE r
       SET r.requirement_statement = p.practice_statement,
           r.objective             = p.objective,
           r.keywords              = p.keywords,
           r.updated_by            = @by,
           r.updated_dt            = SYSUTCDATETIME()
    FROM GRAC_New.requirement r
    JOIN #prac p ON p.practice_name = r.requirement_name
    WHERE r.requirement_statement <> p.practice_statement
       OR ISNULL(r.objective, N'') <> ISNULL(p.objective, N'')
       OR ISNULL(r.keywords,  N'') <> ISNULL(p.keywords,  N'');
    SET @updated = @@ROWCOUNT;
END

-- ---------------------------------------------------------------
-- Practice -> Statement mapping
--
-- Written for every sheet row whose Practice resolves, not only for the
-- rows inserted above: a Practice that already existed may still be
-- missing its link to this release's Statement.
-- ---------------------------------------------------------------
DECLARE @newmap TABLE(statement_requirement_map_id BIGINT, framework_statement_id BIGINT, requirement_id BIGINT);

INSERT GRAC_New.framework_statement_requirement_map
    (framework_statement_id, requirement_id, status, entered_by)
OUTPUT inserted.statement_requirement_map_id, inserted.framework_statement_id, inserted.requirement_id INTO @newmap
SELECT DISTINCT s.framework_statement_id, r.requirement_id, N'Active', @by
FROM #prac p
JOIN #stmt s                ON s.seq = p.seq
JOIN GRAC_New.requirement r ON r.requirement_name = p.practice_name
WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.framework_statement_requirement_map m
                 WHERE m.framework_statement_id = s.framework_statement_id
                   AND m.requirement_id         = r.requirement_id);

SET @mapped = @@ROWCOUNT;

-- Re-activate any mapping that this load covers but that a previous
-- rollback retired, so a rollback-then-reload round trip is clean.
UPDATE m
   SET m.status     = N'Active',
       m.updated_by = @by,
       m.updated_dt = SYSUTCDATETIME()
FROM GRAC_New.framework_statement_requirement_map m
JOIN #stmt s                ON s.framework_statement_id = m.framework_statement_id
JOIN #prac p                ON p.seq                    = s.seq
JOIN GRAC_New.requirement r ON r.requirement_id         = m.requirement_id
                           AND r.requirement_name       = p.practice_name
WHERE m.status <> N'Active';

-- ---------------------------------------------------------------
-- Final assertion: every sheet row now has a Practice AND a mapping.
--
-- 061-065 join Obligations to Practices by name.  A row that silently
-- failed to resolve here would surface there as thousands of skipped
-- Obligations, so it is caught now instead.
-- ---------------------------------------------------------------
IF EXISTS(SELECT 1 FROM #prac p
          WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.requirement r
                           WHERE r.requirement_name = p.practice_name))
BEGIN
    SET @missing = STUFF((SELECT TOP 20 N', ' + p.practice_name FROM #prac p
        WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.requirement r WHERE r.requirement_name = p.practice_name)
        FOR XML PATH('')), 1, 2, N'');
    SET @error = CONCAT(N'Practice(s) not present after load (first 20): ', @missing, N'.');
    THROW 50535, @error, 1;
END

IF EXISTS(SELECT 1 FROM #prac p
          JOIN #stmt s                ON s.seq = p.seq
          JOIN GRAC_New.requirement r ON r.requirement_name = p.practice_name
          WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.framework_statement_requirement_map m
                           WHERE m.framework_statement_id = s.framework_statement_id
                             AND m.requirement_id         = r.requirement_id
                             AND m.status                 = N'Active'))
BEGIN
    SET @error = N'One or more Practices have no active Statement mapping after load. 061-065 inherit the Statement from this mapping and would fail.';
    THROW 50536, @error, 1;
END

-- ---------------------------------------------------------------
-- Audit trail: Practices
--
-- Mirrors the three-table shape cm_manage_repository writes, so these
-- rows render on the Audit Trace screen like any other Add:
--   audit_trace_event  -> one event per Practice
--   audit_trace_detail -> field-level values for that event
--   audit_trace        -> the flat row, linked by audit_event_id
-- action_type is 'Add' to stay inside the existing vocabulary.
--
-- The sheet's Practice ID and Merge Review Status are recorded here --
-- requirement has no column for either, and this is what makes a loaded
-- row traceable back to a spreadsheet line.
-- ---------------------------------------------------------------
DECLARE @events TABLE(audit_event_id BIGINT, entity_id BIGINT);

INSERT GRAC_New.audit_trace_event
    (entity_type,entity_id,action_type,table_name,record_reference,remarks,before_json,after_json,status,entered_by)
OUTPUT inserted.audit_event_id, inserted.entity_id INTO @events
SELECT N'requirements', n.requirement_id, N'Add',
       N'GRAC_New.requirement',
       CONCAT(n.requirement_code, N' - ', n.requirement_name),
       CONCAT(N'Bulk load: migration 060, Import Practice & Obligation Mapping v1.3 (4).xlsx, sheet Practices. Sheet Practice ID: ',
              p.practice_ref, N'. Control: ', p.statement_reference,
              N'. Merge Review Status: ', ISNULL(p.merge_status, N'(none)'), N'.'),
       NULL,
       (SELECT r.requirement_code code, r.requirement_name name,
               r.requirement_statement statement, r.objective, r.keywords, r.status
        FROM GRAC_New.requirement r
        WHERE r.requirement_id = n.requirement_id
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
       N'Active', @by
FROM @new n
JOIN #prac p ON p.practice_name = n.requirement_name;

INSERT GRAC_New.audit_trace_detail(audit_event_id,field_name,old_value,new_value,entered_by)
SELECT e.audit_event_id, d.field_name, NULL, d.new_value, @by
FROM @events e
JOIN GRAC_New.requirement r ON r.requirement_id = e.entity_id
LEFT JOIN #prac p           ON p.practice_name  = r.requirement_name
CROSS APPLY (VALUES
    (N'Practice Code',       r.requirement_code),
    (N'Practice Name',       r.requirement_name),
    (N'Practice Statement',  r.requirement_statement),
    (N'Objective',           r.objective),
    (N'Keywords',            r.keywords),
    (N'Sheet Practice ID',   p.practice_ref),
    (N'Merge Review Status', p.merge_status),
    (N'Status',              r.status)
) AS d(field_name, new_value)
WHERE d.new_value IS NOT NULL;

INSERT GRAC_New.audit_trace
    (audit_event_id,entity_type,entity_id,action_type,table_name,record_reference,remarks,after_json,status,entered_by)
SELECT ev.audit_event_id, ev.entity_type, ev.entity_id, ev.action_type, ev.table_name,
       ev.record_reference, ev.remarks, ev.after_json, N'Active', @by
FROM GRAC_New.audit_trace_event ev
JOIN @events e ON e.audit_event_id = ev.audit_event_id;

-- ---------------------------------------------------------------
-- Audit trail: Practice -> Statement mappings
-- ---------------------------------------------------------------
DECLARE @mapevents TABLE(audit_event_id BIGINT, entity_id BIGINT);

INSERT GRAC_New.audit_trace_event
    (entity_type,entity_id,action_type,table_name,record_reference,remarks,before_json,after_json,status,entered_by)
OUTPUT inserted.audit_event_id, inserted.entity_id INTO @mapevents
SELECT N'source-control-mappings', nm.statement_requirement_map_id, N'Add',
       N'GRAC_New.framework_statement_requirement_map',
       CONCAT(fs.statement_reference, N' -> ', r.requirement_code),
       N'Bulk load: migration 060, Import Practice & Obligation Mapping v1.3 (4).xlsx, sheet Practices.',
       NULL,
       (SELECT fs.framework_statement_id frameworkStatementId,
               fs.statement_reference statementReference,
               r.requirement_id requirementId, r.requirement_code code,
               r.requirement_name name, N'Active' status
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
       N'Active', @by
FROM @newmap nm
JOIN GRAC_New.framework_statement fs ON fs.framework_statement_id = nm.framework_statement_id
JOIN GRAC_New.requirement r          ON r.requirement_id          = nm.requirement_id;

INSERT GRAC_New.audit_trace_detail(audit_event_id,field_name,old_value,new_value,entered_by)
SELECT e.audit_event_id, d.field_name, NULL, d.new_value, @by
FROM @mapevents e
JOIN GRAC_New.framework_statement_requirement_map m ON m.statement_requirement_map_id = e.entity_id
JOIN GRAC_New.framework_statement fs ON fs.framework_statement_id = m.framework_statement_id
JOIN GRAC_New.requirement r          ON r.requirement_id          = m.requirement_id
CROSS APPLY (VALUES
    (N'Framework Statement', fs.statement_reference),
    (N'Practice',            CONCAT(r.requirement_code, N' - ', r.requirement_name)),
    (N'Status',              m.status)
) AS d(field_name, new_value)
WHERE d.new_value IS NOT NULL;

INSERT GRAC_New.audit_trace
    (audit_event_id,entity_type,entity_id,action_type,table_name,record_reference,remarks,after_json,status,entered_by)
SELECT ev.audit_event_id, ev.entity_type, ev.entity_id, ev.action_type, ev.table_name,
       ev.record_reference, ev.remarks, ev.after_json, N'Active', @by
FROM GRAC_New.audit_trace_event ev
JOIN @mapevents e ON e.audit_event_id = ev.audit_event_id;

COMMIT TRANSACTION;

PRINT CONCAT(N'060 complete. Release ', @release_id,
             N' | Practices inserted ', @inserted,
             N' | refreshed ', @updated,
             N' | skipped ', @sheet_rows - @inserted - @updated, N' already present',
             N' | Statement mappings created ', @mapped, N'.');
PRINT N'Next: run 061_iso27001_v13_state.sql.';

END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH
GO

-- ---------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------
-- Practices per Annex A clause. Expect 93 statements carrying 1218
-- Practices in total.
SELECT LEFT(fs.statement_reference, CHARINDEX(N'.', fs.statement_reference) - 1) AS clause,
       COUNT(DISTINCT fs.framework_statement_id) AS statements,
       COUNT(DISTINCT m.requirement_id)          AS practices
FROM GRAC_New.framework_statement_requirement_map m
JOIN GRAC_New.framework_statement fs ON fs.framework_statement_id = m.framework_statement_id
WHERE m.status = N'Active' AND fs.status = N'Active'
GROUP BY LEFT(fs.statement_reference, CHARINDEX(N'.', fs.statement_reference) - 1)
ORDER BY clause;
GO

-- Totals. Expect practices = 1218 and mappings = 1218.
SELECT COUNT(*) AS practices FROM GRAC_New.requirement WHERE status = N'Active';
SELECT COUNT(*) AS statement_mappings FROM GRAC_New.framework_statement_requirement_map WHERE status = N'Active';
GO

-- Any Statement that ended up with no Practice at all. Expect 0 rows.
SELECT fs.framework_statement_id, fs.statement_reference, fs.statement_title
FROM GRAC_New.framework_statement fs
WHERE fs.status = N'Active'
  AND NOT EXISTS(SELECT 1 FROM GRAC_New.framework_statement_requirement_map m
                 WHERE m.framework_statement_id = fs.framework_statement_id
                   AND m.status = N'Active')
ORDER BY fs.statement_reference;
GO
